#include <iostream>

int main() {
    // Khai bao bien ky tu theo vi du giao trinh trang 24
    char c = 65; 
    char d = static_cast<char>(179); // 179 vuot khoi [ -128, 127 ]
    unsigned char e = 179;
    unsigned char f = static_cast<unsigned char>(330); // 330 % 256 = 74

    std::cout << c << " " << static_cast<int>(c) << "\n";
    std::cout << static_cast<int>(d) << "\n";
    std::cout << static_cast<int>(e) << "\n";
    std::cout << static_cast<char>(f) << " " << static_cast<int>(f) << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    // Vi du 2 trang 25: Tinh dien tich hinh tron ban kinh r = 2
    // Hien dai hoa thu vien tu <iostream.h>/<iomanip.h> sang chuan C++17
    float r = 2.0f;
    float area = r * r * 3.1416f;

    std::cout << "Dien tich = " << std::setprecision(3) << std::fixed << area << "\n";

    // Minh hoa cac hang so nguyen o he 10, he 8 va he 16 tu trang 25
    int decVal = 65;
    int octVal = 0101; // Bat phan (Octal)
    int hexVal = 0x41; // Thap luc phan (Hexadecimal)
    long longVal = 123456L;

    std::cout << decVal << " " << octVal << " " << hexVal << " " << longVal << "\n";

    return 0;
}
